/* Interactive Beginner/Architect toggle for the "Learn the architecture" page.
   Loaded site-wide via book.toml `additional-css`; only affects pages that
   contain a [data-mode-toggle] control, so every other chapter is untouched. */

.mode-toggle-bar {
  position: sticky;
  top: var(--menu-bar-height, 0);
  z-index: 5;
  padding: 0.5rem 0;
  margin: 0 0 0.25rem;
  background: var(--bg);
}

.mode-switch {
  display: inline-flex;
  border: 1px solid var(--table-border-color, #bbb);
  border-radius: 8px;
  overflow: hidden;
}

.mode-switch button {
  padding: 0.5rem 1rem;
  border: 0;
  border-right: 1px solid var(--table-border-color, #bbb);
  background: transparent;
  color: var(--fg);
  cursor: pointer;
  font: inherit;
  line-height: 1.2;
}

.mode-switch button:last-child { border-right: 0; }

.mode-switch button.active {
  background: var(--links, #2b79a2);
  color: #fff;
  font-weight: 600;
}

.mode-switch button:hover:not(.active) {
  background: var(--quote-bg, rgba(0, 0, 0, 0.06));
}

.mode-content { display: none; }

.mode-content.active {
  display: block;
  animation: mode-fade 0.18s ease;
}

@keyframes mode-fade {
  from { opacity: 0.35; }
  to   { opacity: 1; }
}

.mode-hint {
  font-size: 0.9em;
  opacity: 0.8;
  margin: 0.25rem 0 1rem;
}

// Interactive Beginner/Architect toggle for the "Learn the architecture" page.
// Loaded site-wide via book.toml `additional-js`. It is a no-op on every page
// that does not contain a [data-mode-toggle] control, so other chapters are
// unaffected. The chosen mode is remembered in localStorage across pages.
(function () {
  "use strict";
  var STORAGE_KEY = "faucet-learn-mode";

  function init() {
    var toggle = document.querySelector("[data-mode-toggle]");
    if (!toggle) return; // not the interactive page

    var buttons = Array.prototype.slice.call(
      toggle.querySelectorAll(".mode-switch button")
    );
    var contents = Array.prototype.slice.call(
      document.querySelectorAll(".mode-content")
    );
    if (!buttons.length || !contents.length) return;

    function apply(mode) {
      buttons.forEach(function (b) {
        var on = b.getAttribute("data-mode") === mode;
        b.classList.toggle("active", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      contents.forEach(function (c) {
        c.classList.toggle("active", c.getAttribute("data-mode") === mode);
      });
      try { localStorage.setItem(STORAGE_KEY, mode); } catch (e) {}
    }

    buttons.forEach(function (b) {
      b.addEventListener("click", function () {
        apply(b.getAttribute("data-mode"));
      });
    });

    var saved = null;
    try { saved = localStorage.getItem(STORAGE_KEY); } catch (e) {}
    apply(saved === "architect" ? "architect" : "beginner");
  }

  if (document.readyState !== "loading") {
    init();
  } else {
    document.addEventListener("DOMContentLoaded", init);
  }
})();

/* ── faucet-stream documentation theme ──────────────────────────────────────
   Visual polish layered on top of mdBook's built-in themes via
   `additional-css` (no preprocessor — a bare `mdbook build` still works).
   Loaded after mdBook's own CSS, so these rules win. Tuned for the two themes
   we ship by default (light + navy); the others (rust/coal/ayu) still inherit
   the brand accent and remain fully legible.
   ──────────────────────────────────────────────────────────────────────── */

:root {
  /* faucet-stream brand — a "water/flow" blue, legible on both light and dark. */
  --fs-brand: #2f7fe0;
  --fs-brand-strong: #1f66c2;
  --fs-accent: #0ea5b7;
  --fs-radius: 8px;
  --content-max-width: 46rem; /* a touch wider than default for tables/code */
}

/* ── Typography ──────────────────────────────────────────────────────────── */
html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, "Noto Sans", sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
  scroll-behavior: smooth;
}
.content {
  line-height: 1.65;
}
.content h1,
.content h2,
.content h3,
.content h4 {
  font-weight: 650;
  letter-spacing: -0.01em;
  line-height: 1.25;
}
.content h1 {
  font-size: 2.1rem;
  padding-bottom: 0.3em;
  border-bottom: 2px solid color-mix(in srgb, var(--fs-brand) 30%, transparent);
}
.content h2 {
  margin-top: 2.2rem;
  padding-bottom: 0.2em;
  border-bottom: 1px solid var(--table-border-color, rgba(128, 128, 128, 0.25));
}

/* ── Links ───────────────────────────────────────────────────────────────── */
.content a:not(.header) {
  color: var(--fs-brand);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.12s ease, color 0.12s ease;
}
.content a:not(.header):hover {
  color: var(--fs-brand-strong);
  border-bottom-color: currentColor;
}

/* ── Code ────────────────────────────────────────────────────────────────── */
.content pre {
  border-radius: var(--fs-radius);
  border: 1px solid var(--table-border-color, rgba(128, 128, 128, 0.2));
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}
.content code {
  border-radius: 4px;
}
.content pre > .buttons {
  opacity: 0.7;
}

/* ── Blockquotes → callouts ──────────────────────────────────────────────── */
.content blockquote {
  border-inline-start: 4px solid var(--fs-brand);
  background: color-mix(in srgb, var(--fs-brand) 8%, transparent);
  border-radius: 0 var(--fs-radius) var(--fs-radius) 0;
  padding: 0.6rem 1rem;
  margin-inline: 0;
  color: inherit;
}

/* ── Tables ──────────────────────────────────────────────────────────────── */
.content table {
  border-radius: var(--fs-radius);
  overflow: hidden;
  border-collapse: collapse;
  width: 100%;
}
.content table thead th {
  background: color-mix(in srgb, var(--fs-brand) 12%, transparent);
  font-weight: 650;
  border-bottom: 2px solid color-mix(in srgb, var(--fs-brand) 30%, transparent);
}
.content table td,
.content table th {
  border: 1px solid var(--table-border-color, rgba(128, 128, 128, 0.18));
  padding: 0.45rem 0.7rem;
}

/* ── Sidebar ─────────────────────────────────────────────────────────────── */
.chapter li.chapter-item a.active {
  color: var(--fs-brand);
  font-weight: 650;
}
.sidebar .sidebar-scrollbox {
  padding: 0.75rem 1rem;
}

/* ── Landing hero (used by introduction.md) ──────────────────────────────── */
.fs-hero {
  text-align: center;
  padding: 1.5rem 0 0.5rem;
}
.fs-hero img {
  max-width: 460px;
  width: 70%;
  height: auto;
}
.fs-hero .fs-tagline {
  font-size: 1.25rem;
  opacity: 0.85;
  margin: 0.75rem auto 1.25rem;
  max-width: 34rem;
  line-height: 1.5;
}
.fs-cta {
  display: inline-flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 1rem;
}
.fs-cta a {
  display: inline-block;
  padding: 0.6rem 1.15rem;
  border-radius: var(--fs-radius);
  font-weight: 600;
  border-bottom: none !important;
}
.fs-cta a.primary {
  background: var(--fs-brand);
  color: #fff !important;
}
.fs-cta a.primary:hover {
  background: var(--fs-brand-strong);
}
.fs-cta a.secondary {
  border: 1px solid var(--fs-brand) !important;
  color: var(--fs-brand) !important;
}

/* Card grid for the landing "why" / quick-links sections. */
.fs-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
  margin: 1.25rem 0;
}
.fs-card {
  border: 1px solid var(--table-border-color, rgba(128, 128, 128, 0.22));
  border-radius: var(--fs-radius);
  padding: 1rem 1.1rem;
  background: color-mix(in srgb, var(--fs-brand) 4%, transparent);
}
.fs-card h3 {
  margin-top: 0;
}

