.sidebar .sidebar-scrollbox {
  padding: 0.6rem 0.8rem;
}
.chapter li.chapter-item {
  margin: 0.12rem 0;
  line-height: 1.5;
}
/* Rounded hover / active "pill" for each TOC entry. */
.chapter li.chapter-item > a,
.chapter li.chapter-item > div {
  border-radius: 7px;
  padding: 0.28rem 0.55rem;
